using System.Reflection;using System.Reflection.Emit;using System.Runtime.CompilerServices;using System.Runtime.Loader;using CounterStrikeSharp.API.Core;using CounterStrikeSharp.API.Modules.Utils;
class Program {
static bool stuck=true,defusing,visible,running,crouching;static float now,jumpStamp,jumpD,jumpT,jumpS,repathD,repathT,repathS;static int jumpReads;
static Vector velocity=new(0,0,0),position=new(0,0,0);static QAngle angles=new(0,0,0);
static CountdownTimer jump=(CountdownTimer)RuntimeHelpers.GetUninitializedObject(typeof(CountdownTimer)),repath=(CountdownTimer)RuntimeHelpers.GetUninitializedObject(typeof(CountdownTimer));
static ref bool Stuck(object o)=>ref stuck;static ref bool Defusing(object o)=>ref defusing;static ref bool Visible(object o)=>ref visible;static ref bool Running(object o)=>ref running;static ref bool Crouching(object o)=>ref crouching;static ref float JumpStamp(object o){jumpReads++;return ref jumpStamp;}
