static ref float Duration(object o){if(ReferenceEquals(o,jump))return ref jumpD;return ref repathD;}static ref float Timestamp(object o){if(ReferenceEquals(o,jump))return ref jumpT;return ref repathT;}static ref float Timescale(object o){if(ReferenceEquals(o,jump))return ref jumpS;return ref repathS;}
static Vector Velocity(object o)=>velocity;static Vector Position(object o)=>position;static QAngle Angles(object o)=>angles;static float Now()=>now;
