static void Main(string[] args){var api=Path.GetFullPath(args[0]);AssemblyLoadContext.Default.Resolving+=(_,n)=>{var p=Path.Combine(api,n.Name+".dll");return File.Exists(p)?AssemblyLoadContext.Default.LoadFromAssemblyPath(p):null;};
var old=Prepare(args[1]);var repaired=Prepare(args[2]);
(int attempts,int timerReads,List<float> times) Run((object obj,MethodInfo original,DynamicMethod mapped) test,bool attack=false,bool defuse=false,bool enemy=false,bool fastButBlocked=false,bool progress=false){Reset();position.X=position.Y=0;foreach(var f in test.obj.GetType().GetFields(BindingFlags.Instance|BindingFlags.NonPublic))if(f.FieldType.IsGenericType && f.FieldType.GetGenericTypeDefinition()==typeof(Dictionary<,>))f.FieldType.GetMethod("Clear")!.Invoke(f.GetValue(test.obj),null);defusing=defuse;visible=enemy;var times=new List<float>();int last=0;for(int i=0;i<=24;i++){now=i*0.5f;velocity.Y=0;velocity.X=fastButBlocked||progress?40:0;position.X=progress?i*10:0;test.mapped.Invoke(null,new object?[]{test.obj,null,RuntimeHelpers.GetUninitializedObject(typeof(CCSPlayerPawn)),RuntimeHelpers.GetUninitializedObject(typeof(CCSBot)),7,now,attack});var field=test.obj.GetType().GetField("_stuckJumpCount",BindingFlags.Instance|BindingFlags.NonPublic)!;var counts=(Dictionary<int,int>)field.GetValue(test.obj)!;int n=counts.GetValueOrDefault(7);if(n>last)times.Add(now);last=n;}return(last,jumpReads,times);}
var a=Run(old);var b=Run(repaired);Check(a.attempts==1 && a.timerReads>20,"original actual IL reproduces one-attempt latch plus per-tick jump resets");Check(b.attempts==4 && b.times.SequenceEqual(new[]{3f,6f,9f,12f}),"repaired actual IL retries after sustained no progress every 3 seconds");Check(Run(repaired,fastButBlocked:true).times.SequenceEqual(new[]{5f,10f}),"slow/no-net-progress branch retries at 5-second intervals");Check(Run(repaired,progress:true).attempts==0,"real horizontal progress prevents recovery even if native stuck flag lags");Check(b.timerReads==0,"repaired IL leaves native jump timers untouched");
Check(Run(repaired,attack:true).attempts==0,"attack suppresses all recovery writes");Check(Run(repaired,defuse:true).attempts==0,"defuse suppresses all recovery writes");Check(Run(repaired,enemy:true).attempts==0,"visible enemy suppresses recovery");
// Execute the actual unmodified method body (not remapped) on its safe guard path.
repaired.original.Invoke(repaired.obj,new object?[]{null,null,null,7,0f,true});Check(true,"actual adapted DLL JITs and returns safely before native access while attacking");
