static void Reset(){stuck=true;defusing=visible=running=crouching=false;now=0;jumpReads=0;}
static (object obj,MethodInfo original,DynamicMethod mapped) Prepare(string path){var ctx=new AssemblyLoadContext(Guid.NewGuid().ToString(),true);ctx.Resolving+=(_,n)=>AssemblyLoadContext.Default.Assemblies.FirstOrDefault(a=>a.GetName().Name==n.Name);var asm=ctx.LoadFromAssemblyPath(Path.GetFullPath(path));var t=asm.GetType("BotState.BotState")!;var flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;var method=t.GetMethod("RecoverStuckBot",flags)!;var obj=RuntimeHelpers.GetUninitializedObject(t);foreach(var f in t.GetFields(flags))if(f.FieldType.IsGenericType && f.FieldType.GetGenericTypeDefinition()==typeof(Dictionary<,>))f.SetValue(obj,Activator.CreateInstance(f.FieldType));
var body=method.GetMethodBody()!;var il=body.GetILAsByteArray()!;var dynamic=new DynamicMethod("RecoveryIL",typeof(void),new[]{t}.Concat(method.GetParameters().Select(p=>p.ParameterType)).ToArray(),typeof(Program).Module,true);var gen=dynamic.GetILGenerator();foreach(var l in body.LocalVariables)gen.DeclareLocal(l.LocalType,l.IsPinned);
var ops=typeof(OpCodes).GetFields(BindingFlags.Static|BindingFlags.Public).Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)!).ToDictionary(o=>unchecked((ushort)o.Value));var labels=new Dictionary<int,Label>();Label L(int at){if(!labels.TryGetValue(at,out var v))labels[at]=v=gen.DefineLabel();return v;}
var records=new List<(int at,OpCode op,int pos,int len)>();for(int p=0;p<il.Length;){int at=p;ushort k=il[p++];if(k==0xfe)k=(ushort)(0xfe00|il[p++]);var op=ops[k];int len=op.OperandType switch{OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,_=>4};records.Add((at,op,p,len));if(op.OperandType==OperandType.InlineBrTarget)L(p+4+BitConverter.ToInt32(il,p));if(op.OperandType==OperandType.ShortInlineBrTarget)L(p+1+(sbyte)il[p]);p+=len;}
var mocks=new Dictionary<string,string>{{"get_IsStuck","Stuck"},{"get_IsDefusing","Defusing"},{"get_IsEnemyVisible","Visible"},{"get_IsRunning","Running"},{"get_IsCrouching","Crouching"},{"get_JumpTimestamp","JumpStamp"},{"get_StuckJumpTimer","Jump"},{"get_RepathTimer","Repath"},{"get_Duration","Duration"},{"get_Timestamp","Timestamp"},{"get_Timescale","Timescale"},{"get_AbsVelocity","Velocity"},{"get_AbsOrigin","Position"},{"get_EyeAngles","Angles"},{"get_CurrentTime","Now"}};
foreach(var (at,op,p,len) in records){if(labels.TryGetValue(at,out var label))gen.MarkLabel(label);switch(op.OperandType){case OperandType.InlineNone:gen.Emit(op);break;case OperandType.ShortInlineBrTarget:gen.Emit(op,L(p+1+(sbyte)il[p]));break;case OperandType.InlineBrTarget:gen.Emit(op,L(p+4+BitConverter.ToInt32(il,p)));break;case OperandType.InlineField:gen.Emit(op,method.Module.ResolveField(BitConverter.ToInt32(il,p))!);break;case OperandType.InlineMethod:var called=method.Module.ResolveMethod(BitConverter.ToInt32(il,p))!;if(mocks.TryGetValue(called.Name,out var mock))gen.Emit(OpCodes.Call,typeof(Program).GetMethod(mock,BindingFlags.Static|BindingFlags.NonPublic)!);else if(called is ConstructorInfo ci)gen.Emit(op,ci);else gen.Emit(op,(MethodInfo)called);break;case OperandType.ShortInlineVar:gen.Emit(op,il[p]);break;case OperandType.InlineVar:gen.Emit(op,BitConverter.ToInt16(il,p));break;case OperandType.ShortInlineR:gen.Emit(op,BitConverter.ToSingle(il,p));break;case OperandType.InlineI:gen.Emit(op,BitConverter.ToInt32(il,p));break;case OperandType.ShortInlineI:gen.Emit(op,(sbyte)il[p]);break;default:throw new Exception("Unexpected opcode operand "+op);}}
return(obj,method,dynamic);}
}
